'use client';
import type { DemoState, Suggestion } from '@seapilot/contracts';
import { Card, Avatar, Badge, Button, SourceBadge, EvidenceTile, ArrowRight, CheckCircle2, Clock3, History, Link2, Package, Sparkles, Truck } from '@seapilot/ui';

interface Props {
  state: DemoState; linked: boolean; suggestion: Suggestion | null; busy: boolean;
  onEvidence: (parcel: 'A' | 'B') => void; onUseDraft: () => void; onEscalate: () => void;
  rejected: boolean; onRestore: () => void;
}
export function CasePanel({ state, linked, suggestion, busy, onEvidence, onUseDraft, onEscalate, rejected, onRestore }: Props) {
  const supportCase = state.case;
  return <aside className="case-pane" aria-label="Case details">
    <div className="case-heading"><h2>Case context</h2>{supportCase && <Badge>{supportCase.id}</Badge>}</div>
    {!linked ? <div className="case-section"><div className="row" style={{ marginBottom: 16 }}><Link2 size={20} className="muted" /><h3 style={{ margin: 0 }}>{supportCase ? 'A familiar story' : 'Start with one case'}</h3></div><p>{supportCase ? 'Lan already has a case for this order. Confirm the match to bring the earlier conversation, evidence, and next step into view.' : 'Create a case from the customer’s message to keep the conversation and evidence together.'}</p>{supportCase && <div className="action-box"><strong>CS001 · Cap not received</strong><p>Order DH001 · Lan Nguyen</p><div className="row small muted"><History size={14} />Earlier conversation and attachment on file</div></div>}</div> : <>
    <Card className="case-section"><div className="row between" style={{ marginBottom: 14 }}><h3 style={{ margin: 0 }}>Cap not received<SourceBadge source="system" /></h3><Badge tone={supportCase?.status === 'waiting_ops' ? 'amber' : 'green'}>{supportCase?.status === 'waiting_ops' ? 'Waiting on ops' : 'Open'}</Badge></div><dl className="case-info"><div><dt>Assigned to</dt><dd className="row"><Avatar small name={supportCase?.assignee ?? 'An'} />{supportCase?.assignee}</dd></div><div><dt>Customer</dt><dd>Lan Nguyen</dd></div><div><dt>Order</dt><dd>DH001</dd></div><div><dt>Team</dt><dd>Delivery & Logistics <SourceBadge source="unverified" /></dd></div></dl></Card>
    <Card className="case-section"><h3><Package size={15} />Order & parcels<SourceBadge source="system" /></h3><div className="parcel-row"><span className="parcel-name"><Package size={16} />A · T-shirt</span><Badge tone="green">Delivered</Badge></div><div className="parcel-row"><span className="parcel-name"><Package size={16} />B · Cap</span><Badge tone={state.parcelB === 'delivered' ? 'green' : 'amber'}>{state.parcelB === 'delivered' ? 'Marked delivered' : 'In transit'}</Badge></div></Card>
    <Card className="case-section suggestion-card"><div className="row between" style={{ marginBottom: 14 }}><h3 className="suggestion-heading" style={{ margin: 0 }}><Sparkles size={16} />Suggested next step</h3><Badge>Demo fixture</Badge></div>
      {supportCase?.lastReplyParcelB === 'in_transit' && state.parcelB === 'delivered' && <div className="change-highlight"><h4>What changed since the last reply</h4><p className="small" style={{ marginBottom: 7 }}>Parcel B · carrier status</p><div className="change-flow"><s>In transit</s><ArrowRight size={13} /><strong>Delivered</strong></div></div>}
      {suggestion && !rejected ? <><div className="facts">{suggestion.facts.map(fact => <p className="fact" key={fact.source}><SourceBadge source={fact.source} />{fact.text}</p>)}</div><div className="missing-fact"><strong>{suggestion.question ? 'One thing still missing' : 'No more information needed'}</strong><p>{suggestion.question ?? 'Use the evidence already on file to continue this case.'}</p></div><Button variant="secondary" style={{ width: '100%', marginTop: 16 }} onClick={onUseDraft} disabled={busy}><Sparkles />Use suggested reply</Button>
      {suggestion.action && <div className="action-box"><strong>Ask operations to check packing</strong><p>Attach both parcel references. No refund or replacement is promised.</p><Button size="sm" onClick={onEscalate} disabled={busy}>{busy ? 'Saving…' : 'Approve escalation'}<ArrowRight /></Button></div>}
      {supportCase?.taskId && <div className="action-box"><div className="row"><CheckCircle2 size={17} /><strong>Escalation recorded</strong></div><p>OPS001 · Warehouse Ops<br />Both evidence references attached.</p><p>Review and send the updated reply to let Lan know.</p></div>}</> : <><p className="muted">Suggestion dismissed. You can write a reply yourself or review the fixture again.</p><Button variant="outline" size="sm" onClick={onRestore} style={{ marginTop: 12 }}>Review suggestion</Button></>}
    </Card>
    <Card className="case-section"><div className="row between"><h3 style={{ margin: 0 }}>Evidence on file</h3><span className="small muted">{supportCase?.evidence.length} attached</span></div><div className="evidence-grid">{supportCase?.evidence.map(id => <EvidenceTile key={id} parcel={id === 'parcel-a' ? 'A' : 'B'} onClick={() => onEvidence(id === 'parcel-a' ? 'A' : 'B')} />)}</div><p className="muted" style={{ fontSize: 10, marginTop: 10 }}>Customer-supplied references · illustrative placeholders</p></Card>
    <Card className="case-section"><h3><Clock3 size={15} />Case timeline</h3><div className="timeline">{supportCase?.events.slice().reverse().map(event => <div className="timeline-item" key={event.id}><span className="timeline-dot" /><div>{event.text}<time>{event.time}</time></div></div>)}</div></Card>
    </>}
    <div className="case-section"><p className="muted" style={{ fontSize: 10 }}><Truck size={13} style={{ display: 'inline', marginRight: 6 }} />Delivered describes the parcel, not its contents.</p></div>
  </aside>;
}
import { z } from 'zod';

const id = z.string().min(1);
const time = z.iso.datetime({ offset: true });
export const CustomerRowSchema = z.object({ id, name: z.string(), email: z.email(), language: z.string() });
export const OrderRowSchema = z.object({ id, customer_id: id, placed_at: time, status: z.string() });
export const OrderItemRowSchema = z.object({ id, order_id: id, sku: z.string(), name: z.string(), qty: z.number().int().positive(), parcel_code: z.string() });
export const ShipmentRowSchema = z.object({ id, order_id: id, parcel_code: z.string(), carrier: z.string(), tracking: z.string(), status: z.string(), updated_at: time });
export const CaseRowSchema = z.object({ id, order_id: id, customer_id: id, title: z.string(), status: z.enum(['open', 'waiting_customer', 'waiting_ops', 'resolved']), assignee: z.string(), created_at: time });
export const ConversationRowSchema = z.object({ id, customer_id: id, case_id: id.nullable(), channel: z.string(), mode: z.enum(['human', 'auto']).default('human'), opened_at: time });
export const MessageRowSchema = z.object({ id, conversation_id: id, role: z.enum(['customer', 'cs', 'ai']), text: z.string(), actor: z.string(), created_at: time });
export const EvidenceRowSchema = z.object({ id, conversation_id: id, case_id: id.nullable(), type: z.string(), path: z.string(), source: z.enum(['customer', 'system', 'unverified']), created_at: time });
export const CaseEventRowSchema = z.object({ id, case_id: id, type: z.string(), actor: z.string(), payload: z.record(z.string(), z.unknown()), created_at: time });
export const TaskRowSchema = z.object({ id, case_id: id, team: z.string(), status: z.string(), evidence_ids: z.array(id), created_at: time });

export const DbRowSchemas = {
  customers: CustomerRowSchema, orders: OrderRowSchema, order_items: OrderItemRowSchema,
  shipments: ShipmentRowSchema, cases: CaseRowSchema, conversations: ConversationRowSchema,
  messages: MessageRowSchema, evidence: EvidenceRowSchema, case_events: CaseEventRowSchema, tasks: TaskRowSchema,
};
export type DbRows = { [K in keyof typeof DbRowSchemas]: z.infer<(typeof DbRowSchemas)[K]> };
export type DbTable = keyof DbRows;
export const DatabaseStateSchema = z.object({
  customers: z.array(CustomerRowSchema), orders: z.array(OrderRowSchema), order_items: z.array(OrderItemRowSchema),
  shipments: z.array(ShipmentRowSchema), cases: z.array(CaseRowSchema), conversations: z.array(ConversationRowSchema),
  messages: z.array(MessageRowSchema), evidence: z.array(EvidenceRowSchema), case_events: z.array(CaseEventRowSchema), tasks: z.array(TaskRowSchema),
});
export type DatabaseState = z.infer<typeof DatabaseStateSchema>;
import { z } from 'zod';

export const AgentSuggestionSchema = z.object({
  suggested_case_id: z.string().nullable(),
  link_confidence: z.number().min(0).max(1),
  link_reason: z.string(),
  known_facts: z.array(z.object({ text: z.string(), source: z.enum(['customer', 'system', 'unverified']) })),
  changes: z.array(z.object({ text: z.string(), before: z.string(), after: z.string() })),
  missing_info: z.array(z.string()).max(1),
  draft_reply: z.string(),
  proposed_action: z.object({
    type: z.literal('escalate_to_ops'), reason: z.string(), evidence_ids: z.array(z.string()),
  }).nullable(),
});
export type AgentSuggestion = z.infer<typeof AgentSuggestionSchema>;

export const AgentSuggestionEnvelopeSchema = z.object({
  ok: z.boolean(), suggestion: AgentSuggestionSchema.nullable(), error: z.string().optional(),
});
export type AgentSuggestionEnvelope = z.infer<typeof AgentSuggestionEnvelopeSchema>;
export const SuggestRequestSchema = z.object({ conversation_id: z.string().min(1) });
'use client';
import { useRef, useState } from 'react';
import type { DemoCommand, Scene } from '@seapilot/contracts';
import { createDemoState, transition } from './index';

/** An in-memory fixture boundary. It intentionally never contacts a service. */
export function useDemo(initialScene: Scene = 'returning') {
  const [state, setState] = useState(() => createDemoState(initialScene));
  const current = useRef(state);
  const generation = useRef(0);
  const pending = useRef(false);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');
  const [notice, setNotice] = useState('');
  async function perform(command: DemoCommand, success: string) {
    if (pending.current) return false;
    pending.current = true; setBusy(true); setError(''); setNotice('');
    const started = generation.current;
    await new Promise(resolve => setTimeout(resolve, 250));
    if (started !== generation.current) return false;
    try {
      const next = transition(current.current, command);
      current.current = next; setState(next); setNotice(success); return true;
    } catch (error) {
      setError(error instanceof Error ? error.message : 'That change could not be saved. Try again.');
      return false;
    } finally { pending.current = false; setBusy(false); }
  }
  function reset(scene: Scene) {
    generation.current += 1; pending.current = false;
    const next = createDemoState(scene); current.current = next; setState(next);
    setBusy(false); setError(''); setNotice('Local demo reset.');
  }
  return { state, busy, error, notice, perform, reset };
}
